CREATE TABLE public.one_time_data_operations(operation_key text PRIMARY KEY,consumed_at timestamptz NOT NULL DEFAULT now(),result jsonb NOT NULL DEFAULT '{}'::jsonb);
GRANT ALL ON public.one_time_data_operations TO service_role;
REVOKE ALL ON public.one_time_data_operations FROM anon,authenticated;
ALTER TABLE public.one_time_data_operations ENABLE ROW LEVEL SECURITY;
CREATE FUNCTION public.reset_customer_zones_once() RETURNS jsonb LANGUAGE plpgsql SECURITY INVOKER SET search_path=public AS $$
DECLARE deleted jsonb; pre jsonb; post jsonb; fingerprints jsonb; verified jsonb; n integer;
BEGIN
IF session_user<>'postgres' OR current_user<>'postgres' OR auth.uid() IS NOT NULL OR coalesce(current_setting('role',true),'none')<>'none' THEN RAISE EXCEPTION 'Privileged operator required'; END IF;
LOCK TABLE public.one_time_data_operations IN EXCLUSIVE MODE;
IF EXISTS(SELECT 1 FROM public.one_time_data_operations WHERE operation_key='demo-reset-2026-11-09') THEN RAISE EXCEPTION 'Reset already consumed'; END IF;
LOCK TABLE public.collectors,public.user_roles IN SHARE MODE;
LOCK TABLE public.customers,public.zones,public.monthly_bills,public.payments,public.payment_allocations IN ACCESS EXCLUSIVE MODE;
IF (SELECT md5(string_agg(conrelid::regclass::text||'|'||confrelid::regclass::text||'|'||pg_get_constraintdef(oid),E'\n' ORDER BY conrelid::regclass::text,confrelid::regclass::text,pg_get_constraintdef(oid))) FROM pg_constraint WHERE contype='f' AND (conrelid IN ('public.customers'::regclass,'public.zones'::regclass,'public.monthly_bills'::regclass,'public.payments'::regclass,'public.payment_allocations'::regclass) OR confrelid IN ('public.customers'::regclass,'public.zones'::regclass,'public.monthly_bills'::regclass,'public.payments'::regclass,'public.payment_allocations'::regclass))) IS DISTINCT FROM 'ba1f115410902aa222f1a21b3f6ffca1' THEN RAISE EXCEPTION 'Live bidirectional FK mismatch'; END IF;
IF (SELECT md5(string_agg(t.tgrelid::regclass::text||':'||t.tgname::text||':'||t.tgenabled::text||':'||pg_get_triggerdef(t.oid)||':'||pg_get_functiondef(t.tgfoid),E'\n' ORDER BY t.tgrelid::regclass::text,t.tgname)) FROM pg_trigger t WHERE NOT t.tgisinternal AND t.tgrelid IN ('public.customers'::regclass,'public.zones'::regclass,'public.monthly_bills'::regclass,'public.payments'::regclass,'public.payment_allocations'::regclass)) IS DISTINCT FROM '79d7ba2944426b0c3f0665af5b0ea7f0' THEN RAISE EXCEPTION 'Live trigger mismatch'; END IF;
SELECT jsonb_build_object('customers',(SELECT count(*) FROM public.customers),'zones',(SELECT count(*) FROM public.zones),'monthly_bills',(SELECT count(*) FROM public.monthly_bills),'payments',(SELECT count(*) FROM public.payments),'payment_allocations',(SELECT count(*) FROM public.payment_allocations)) INTO pre;
IF pre IS DISTINCT FROM '{"customers":42,"zones":2,"monthly_bills":83,"payments":45,"payment_allocations":13}'::jsonb THEN RAISE EXCEPTION 'Authorized demo counts changed'; END IF;
IF EXISTS(SELECT 1 FROM public.payment_allocations a LEFT JOIN public.payments p ON p.id=a.payment_id LEFT JOIN public.monthly_bills b ON b.id=a.bill_id LEFT JOIN public.customers c ON c.id=p.customer_id LEFT JOIN public.customers d ON d.id=b.customer_id WHERE p.id IS NULL OR b.id IS NULL OR c.id IS NULL OR d.id IS NULL OR p.customer_id IS DISTINCT FROM b.customer_id) THEN RAISE EXCEPTION 'Mixed or missing ownership'; END IF;
SELECT jsonb_build_object('collectors',(SELECT md5(jsonb_agg(to_jsonb(c) ORDER BY c.id)::text) FROM public.collectors c),'user_roles',(SELECT md5(jsonb_agg(to_jsonb(r) ORDER BY r.user_id)::text) FROM public.user_roles r),'auth_users',(SELECT md5(jsonb_agg(to_jsonb(u) ORDER BY u.id)::text) FROM auth.users u)) INTO fingerprints;
INSERT INTO public.one_time_data_operations(operation_key) VALUES('demo-reset-2026-11-09');
ALTER TABLE public.customers DISABLE TRIGGER guard_customer_delete;
ALTER TABLE public.zones DISABLE TRIGGER guard_zone_delete;
ALTER TABLE public.monthly_bills DISABLE TRIGGER validate_monthly_bill;
DELETE FROM public.payment_allocations a USING public.payments p,public.monthly_bills b WHERE a.payment_id=p.id AND a.bill_id=b.id AND p.customer_id=b.customer_id;
GET DIAGNOSTICS n=ROW_COUNT; deleted:=jsonb_build_object('payment_allocations',n);
DELETE FROM public.monthly_bills b USING public.customers c WHERE b.customer_id=c.id;
GET DIAGNOSTICS n=ROW_COUNT; deleted:=deleted||jsonb_build_object('monthly_bills',n);
DELETE FROM public.payments p USING public.customers c WHERE p.customer_id=c.id;
GET DIAGNOSTICS n=ROW_COUNT; deleted:=deleted||jsonb_build_object('payments',n);
DELETE FROM public.customers WHERE id IS NOT NULL;
GET DIAGNOSTICS n=ROW_COUNT; deleted:=deleted||jsonb_build_object('customers',n);
DELETE FROM public.zones WHERE id IS NOT NULL;
GET DIAGNOSTICS n=ROW_COUNT; deleted:=deleted||jsonb_build_object('zones',n);
ALTER TABLE public.customers ENABLE TRIGGER guard_customer_delete;
ALTER TABLE public.zones ENABLE TRIGGER guard_zone_delete;
ALTER TABLE public.monthly_bills ENABLE TRIGGER validate_monthly_bill;
SELECT jsonb_build_object('collectors',(SELECT md5(jsonb_agg(to_jsonb(c) ORDER BY c.id)::text) FROM public.collectors c),'user_roles',(SELECT md5(jsonb_agg(to_jsonb(r) ORDER BY r.user_id)::text) FROM public.user_roles r),'auth_users',(SELECT md5(jsonb_agg(to_jsonb(u) ORDER BY u.id)::text) FROM auth.users u)) INTO verified;
IF fingerprints IS DISTINCT FROM verified THEN RAISE EXCEPTION 'Preserved records changed'; END IF;
SELECT jsonb_build_object('customers',(SELECT count(*) FROM public.customers),'zones',(SELECT count(*) FROM public.zones),'monthly_bills',(SELECT count(*) FROM public.monthly_bills),'payments',(SELECT count(*) FROM public.payments),'payment_allocations',(SELECT count(*) FROM public.payment_allocations)) INTO post;
IF deleted IS DISTINCT FROM pre OR post IS DISTINCT FROM '{"customers":0,"zones":0,"monthly_bills":0,"payments":0,"payment_allocations":0}'::jsonb THEN RAISE EXCEPTION 'Reset counts mismatch'; END IF;
UPDATE public.one_time_data_operations SET result=jsonb_build_object('before',pre,'deleted',deleted,'after',post,'preserved_before',fingerprints,'preserved_after',verified) WHERE operation_key='demo-reset-2026-11-09';
RETURN jsonb_build_object('before',pre,'deleted',deleted,'after',post,'preserved_before',fingerprints,'preserved_after',verified);
END; $$;
REVOKE ALL ON FUNCTION public.reset_customer_zones_once() FROM PUBLIC,anon,authenticated,service_role;
COMMENT ON FUNCTION public.reset_customer_zones_once() IS 'Privileged one-time confirmed demo reset; durable consumed marker prevents reuse. Retire after success.';